mapper.select:
select tr.tenant_id, tr.workflow_definition_id, tr.biz_date,
       tr.request_id, tr.trace_id, tr.request_status, tr.updated_at
from batch.trigger_request tr
where tr.tenant_id = #{tenantId}
  and tr.workflow_definition_id = #{workflowDefinitionId}
  and (tr.dedup_key = #{idempotencyKey} or exists (
      select 1 from batch.trigger_request_idempotency_alias alias
      where alias.tenant_id = tr.tenant_id
        and alias.request_id = tr.request_id
        and alias.idempotency_key = #{idempotencyKey}
  ))
